const now = new Date();
const warsaw = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Warsaw' }));
const yyyy = warsaw.getFullYear();
const mm = String(warsaw.getMonth() + 1).padStart(2, '0');
const dd = String(warsaw.getDate()).padStart(2, '0');
const dateIso = `${yyyy}-${mm}-${dd}`;
const dateParam = `${yyyy}${mm}${dd}`;
return [{
  json: {
    trade_date: dateIso,
    date_param: dateParam,
    month_param: mm,
    year_param: String(yyyy),
    source_url: `https://www.bondspot.pl/notowania_TBSPoland?date=${dateParam}&month=${mm}&year=${yyyy}`
  }
}];

// Parse the 'PODSUMOWANIE OBROTU - OBLIGACJE PLN' table.
// Returns ONE item per input item: {trade_date, source_url, rows, rows_count, status}.
const out = [];
for (const item of $input.all()) {
  const meta = $('Build Fetch Item (today)').item.json;
  const source = String(item.json.data || item.json.body || item.json.raw || '');

  const parseNum = (s) => {
    if (s === undefined || s === null) return null;
    let t = String(s).replace(/&nbsp;/g, ' ').trim();
    if (t === '' || t === '-' || t === '\u2013' || t === '\u2014') return null;
    t = t.replace(/\s/g, '').replace(',', '.');
    const n = parseFloat(t);
    return Number.isFinite(n) ? n : null;
  };

  // Locate the OBLIGACJE PLN table. In 2011 the title is just 'OBLIGACJE' (no PLN suffix).
  const titleRx = /<th[^>]*>\s*<strong>\s*PODSUMOWANIE OBROTU - OBLIGACJE(?:\s+PLN)?\s*<\/strong>\s*<\/th>/i;
  const titleMatch = source.match(titleRx);
  let rows = [];
  if (titleMatch) {
    const tableStart = titleMatch.index;
    const tableEnd = source.indexOf('</table>', tableStart);
    const slice = tableEnd > 0 ? source.slice(tableStart, tableEnd) : source.slice(tableStart);

    const rowRegex = /<tr>\s*<td>([^<]+)<\/td>\s*<td>(PL[A-Z0-9]{10})\s*<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<td[^>]*>([^<]*)<\/td>\s*<\/tr>/g;

    let m;
    while ((m = rowRegex.exec(slice)) !== null) {
      rows.push({
        trade_date: meta.trade_date,
        isin: m[2].trim(),
        name: m[1].trim(),
        bid_price: parseNum(m[3]),
        ask_price: parseNum(m[4]),
        first_price: parseNum(m[5]),
        max_price: parseNum(m[6]),
        min_price: parseNum(m[7]),
        last_price: parseNum(m[8]),
        avg_price: parseNum(m[9]),
        volume: parseNum(m[10]),
        value_mln_pln: parseNum(m[11]),
        trade_count: parseNum(m[12]),
        source_url: meta.source_url
      });
    }
  }

  out.push({
    json: {
      trade_date: meta.trade_date,
      source_url: meta.source_url,
      rows,
      rows_count: rows.length,
      status: rows.length > 0 ? 'ok' : 'empty'
    }
  });
}
return out;
